class Counter(var count: Int) {
    fun add(step: Int) {
        count = count + step
    }

    fun addTwice(step: Int) {
        add(step)
        add(step)
    }
}

fun main() {
    val a = Counter(0)
    val b = Counter(10)
    a.addTwice(3)
    b.add(1)
    println(a.count)
    println(b.count)
}

